#include <bits/stdc++.h>

using namespace std;

const long long kMOD = 1000000007LL;

struct Mat {
    vector<vector<long long>> a;
    int n, m;

    Mat(const vector<vector<long long>>& a)
        : a(a), n(static_cast<int>(a.size())),
          m(a.empty() ? 0 : static_cast<int>(a[0].size())) {}

    Mat(int n, int m, int val = 0) : a(n, vector<long long>(m, 0)), n(n), m(m) {
        for (int i = 0; i < min(n, m); ++i) {
            a[i][i] = val;
        }
    }

    const vector<long long>& operator[](int i) const {
        return a[i];
    }

    vector<long long>& operator[](int i) {
        return a[i];
    }

    Mat operator*(const Mat& B) const {
        assert(m == B.n);
        Mat ans(n, B.m);

        for (int i = 0; i < n; ++i) {
            for (int k = 0; k < m; ++k) {
                if (a[i][k] == 0) continue;
                for (int j = 0; j < B.m; ++j) {
                    if (B[k][j] == 0) continue;
                    long long add = a[i][k] * B[k][j] % kMOD;
                    ans[i][j] += add;
                    if (ans[i][j] >= kMOD) ans[i][j] -= kMOD;
                }
            }
        }
        return ans;
    }

    void print() const {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                cout << a[i][j] << ' ';
            }
            cout << '\n';
        }
    }
};

Mat b_pow(Mat A, long long deg) {
    assert(A.n == A.m);
    Mat result(A.n, A.n, 1);

    while (deg > 0) {
        if (deg & 1LL) result = result * A;
        deg >>= 1LL;
        if (deg > 0) A = A * A;
    }
    return result;
}

long long pow2(int exponent) {
    long long result = 1;
    long long base = 2;

    while (exponent > 0) {
        if (exponent & 1) result = result * base % kMOD;
        base = base * base % kMOD;
        exponent >>= 1;
    }
    return result;
}

