                    ans[i][j] += (a[i][k] * B[k][j]) % kMOD;
                }
                ans[i][j] %= kMOD;
            }
        }
        return ans;
    }

    void print () const {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                cout << a[i][j] << " ";
            }
            cout << "\n";
        }
    }
};

Mat b_pow (Mat A, int deg) {
    if (deg == 0) return Mat(A.n, A.m, 1);
    if (deg == 1) return A;
    if (deg == 2) return A * A;
    return deg % 2 ? b_pow(A, deg / 2) * b_pow(A, deg / 2 + 1) :
                     b_pow(b_pow(A, deg / 2), 2);
}

int main() {
#ifdef _DEBUG
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
