    long long n, k;
    cin >> n >> k;
    Mat A(2 * k + 3, 2 * k + 3);
    vector<long long> c(k + 1, 0);
    c[0] = 1;
    for (int i = 1; i < k + 1; ++i) {
        long long b = 0;
        for (int j = 0; j <= i; ++j) {
            long long t = b;
            b = c[j] % kMOD;
            c[j] += t;
            c[j] %= kMOD;
        }
    }
    for (int i = 0; i < k + 1; ++i) {
        A[i][i + k + 1] = 1;
        for (int j = 0; j <= i; ++j) {
            A[i + k + 1][j + k + 1] = (A[i + k][j + k] + A[i + k][j + k + 1]) % kMOD;
            A[k + 1][k + 1] = 1;
            A[i + k + 1][j] = (A[i + k + 1][j + k + 1] * ((1 << (i - j)) % kMOD)) % kMOD;
        }
        A[2 * k + 2][i] = (c[i] * ((1 << (k - i)) % kMOD)) % kMOD;
        A[2 * k + 2][i + k + 1] = c[i];   
    }
    A[2 * k + 2][2 * k + 2] = 1;
    Mat B(2 * k + 3, 1);
    for (int i = 0; i < 2 * k + 3; ++i) {
        B[i][0] = 1;
    }
    for (int i = 1; i < k + 1; ++i) {
        B[i][0] = 0;
    }
    cout << (b_pow(A, n - 1) * B)[2 * k + 2][0] << "\n";
